_A3K = [("Matutuklasan mo rin ang tamang paraan para bumaba ang timbang mo.", "You will also discover the right way to bring your weight down."), ("Masusubaybayan ng trainer ang progreso mo sa paghahanda para sa triathlon.", "The trainer will be able to monitor your progress in the preparation for the triathlon."), ("Nasalihan na yata ni Aurelio ang lahat ng koponan sa takbuhan.", "Aurelio apparently has already joined all the teams in the race."), ("Paano malalaman kung sobra na ang pag-eehersisyo ko?", "How can I know if my exercising is too much already?"), ("Kailangang mabigyan ng pansin hindi lang ang katawan kundi ang kaisipan din.", "Attention needs to be given not only to the body but also to the mind."), ("Baka magustuhan mo rin ang bagong paligsahan sa paglangoy.", "You might like the new swimming competition too.")]
_A3Q = [["ang tamang paraan / ang timbang mo / matutuklasan / mo rin / para bumaba (.)", "Matutuklasan mo rin ang tamang paraan para bumaba ang timbang mo."], ["ang progreso mo / ang timbang mo / masusubaybayan / ng trainer / para sa triathlon / sa paghahanda (.)", "Masusubaybayan ng trainer ang progreso mo sa paghahanda para sa triathlon."], ["ang lahat ng koponan / na yata / nasalihan / ni Aurelio / sa takbuhan (.)", "Nasalihan na yata ni Aurelio ang lahat ng koponan sa takbuhan."], ["ang pag-eehersisyo ko / kung sobra na / malalaman / paano (?)", "Paano malalaman kung sobra na ang pag-eehersisyo ko?"], ["kailangang mabigyan / kundi ang kaisipan din / hindi lang ang katawan / ng pansin (.)", "Kailangang mabigyan ng pansin hindi lang ang katawan kundi ang kaisipan din."], ["ang bagong paligsahan / baka / magustuhan mo / rin / sa paglangoy (.)", "Baka magustuhan mo rin ang bagong paligsahan sa paglangoy."]]
