_A5 = [("May kapasidad na apat na libo at dalawang daang pasyente ang National Center for Mental Health at may humigit kumulang na tatlong libo at apat na raang pasyente.", "The National Center for Mental Health has a capacity of 4,200 patients and has roughly 3,400 patients."), ("Itinatag ang Insular Psychopathic Hospital dahil sa Public Works Act tatlong libo dalawang daan at limampu’t walo noong ika-labimpito ng Disyembre, isang libo siyam na raan at dalawampu’t walo.", "The Insular Psychopathic Hospital was established because of Public Works Act 3258 on December 17, 1928."), ("Itinatag ang National Center for Mental Health noong ika-labindalawa ng Nobyembre isang libo siyam na raan at walumpu’t anim at pinangalanang National Center for Mental Health ayon sa Memo bilang apatnapu’t walo ng Office of the President.", "The National Center for Mental Health was established on November 12, 1986 and named the National Center for Mental Health according to Memo No. 48 of the Office of the President."), ("Nasa apatnapu’t anim punto pito ektarya ang National Center for Mental Health, kasama ang tatlumpu’t limang pavilion at limampu’t dalawang ward.", "The National Center for Mental Health covers about 46.7 hectares, including 35 pavilions and 52 wards."), ("Mga isang libo siyam na raan at siyamnapu’t tatlo ang mga tauhan ng National Center for Mental Health, kasama ang isandaan at labing-anim na doktor at tatlong daan at pitumpu’t limang nars.", "The National Center for Mental Health has about 1,993 personnel, including 116 doctors and 375 nurses.")]
_K5 = [["1", "4,200 – 3,400"], ["2", "3258 – Dec. 17, 1928"], ["3", "Nov. 12, 1986 – 48"], ["4", "46.7 – 35 – 52"], ["5", "1,993 – 116 – 375"]]
_A6 = [("Alam n’yo ba na ang paglalakad ng sampung minuto kada araw ay nakakapagpataas o nakakapagpaganda ng mood ng tao?", "Did you know that walking ten minutes a day raises or improves a person’s mood?"), ("Ayon sa isang pag-aaral sa United Kingdom, bukod sa nakakapagpataas ito ng kumpiyansa sa sarili ay napapababa rin nito ang stress o anumang alalahanin mo sa iyong isip.", "According to a study in the United Kingdom, apart from boosting self-confidence it also lowers stress or any worries in your mind."), ("Nadiskubre din na ang pag-eehersisyo ay kapwa nakakatulong na mapaganda ang takbo ng iyong katawan at ng iyong utak, lalo na kung ikaw ay nakakaranas ng depresyon at pagiging makakalimutin.", "It was also discovered that exercise helps in the smooth running of both your body and your brain, especially if you are experiencing depression and being forgetful."), ("Ang pagtatrabaho sa loob ng bahay at ang paglalakad ay magkaiba.", "Working inside the house and walking are different."), ("Ang pagtatrabaho sa loob ng bahay bilang ehersisyo ay mas lalong makakapagpadagdag ng iyong alalahanin kumpara sa ikaw ay maglalakad sa labas ng iyong bahay.", "Working inside the house as exercise will further add to your worries compared with walking outside your house."), ("Dito ay malilibang ka at pagpapawisan na magreresulta ng maganda mong pakiramdam.", "Here you will be entertained and will sweat, which will result in feeling good.")]
_K6 = [["1", "bukod sa nakakapagpataas ito ng kumpiyansa sa sarili", "apart from boosting one’s self-confidence"], ["2", "nakakatulong na mapaganda ang takbo ng iyong katawan at ng iyong utak", "helps in the smooth functioning of your body and brain"], ["3", "pagiging makakalimutin", "being forgetful"], ["4", "Ang pagtatrabaho sa loob ng bahay at ang paglalakad ay magkaiba", "working in the house and walking outside the house are different from each other"], ["5", "mas lalong makakapagpadagdag ng iyong alalahanin", "will further add to your worries"]]
_A7 = [("Iwasan ang caffeine.", "Avoid caffeine."), ("Bahagi na yata ng buhay ng maraming tao ang pagkakaroon ng caffeine sa katawan, partikular na ang pag-inom ng kape dahil ito ay mabisang pampagising.", "Having caffeine in the body is probably already part of many people’s lives, particularly drinking coffee because it is an effective wake-up aid."), ("Pero, sa totoo lang, ang pag-inom ng dalawa hanggang tatlong tasa ng kape ay nagpapadami ng bilang ng cortisol hormone sa iyong katawan.", "But, in truth, drinking two to three cups of coffee increases the number of cortisol hormones in your body."), ("Ang cortisol ay isang stress hormone at nagdadala ito ng nerbiyos sa halip na maging alerto.", "Cortisol is a stress hormone and it brings nervousness instead of making you alert."), ("Mas mabuti pang uminom na lang ng malamig na tubig kapag nakakaramdam ng pagkaantok.", "It is better to just drink cold water when you feel sleepy.")]
